('q_mat-zlomky-pocitani_0','Kolik je 1/5 + 2/5?',ARRAY['2/5','3/5','3/10','1/5']::TEXT[],1,'Jmenovatel zůstává, čitatele sečteme: 1 + 2 = 3.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-zlomky-pocitani',NULL,NOW()),
