('q_mat-zlomky-pocitani_2','Který zlomek je větší: 3/8, nebo 5/8?',ARRAY['Jsou stejné','3/8','Nedá se říct','5/8']::TEXT[],3,'Při stejném jmenovateli je větší ten s větším čitatelem.',1,ARRAY[]::TEXT[],NULL,2,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_3','Kolik je 2/7 + 4/7?',ARRAY['6/14','8/7','2/7','6/7']::TEXT[],3,'2 + 4 = 6, jmenovatel zůstává 7.',2,ARRAY[]::TEXT[],NULL,3,'c_mat-zlomky-pocitani',NULL,NOW()),
