('q_mat-zlomky-pocitani_5','Zlomek 1/2 zapsaný se jmenovatelem 4 je…',ARRAY['4/2','3/4','2/4','1/4']::TEXT[],2,'Rozšíříme dvěma: 1/2 = 2/4.',2,ARRAY[]::TEXT[],NULL,5,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_6','Kolik je 3/8 + 1/2?',ARRAY['7/8','5/8','4/8','4/10']::TEXT[],0,'1/2 = 4/8 a 3/8 + 4/8 = 7/8.',3,ARRAY[]::TEXT[],NULL,6,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_7','Zkrať zlomek 6/8.',ARRAY['2/8','3/4','1/2','6/4']::TEXT[],1,'Dělíme čitatele i jmenovatele dvěma.',3,ARRAY[]::TEXT[],NULL,7,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_8','Kolik je 7/10 − 3/10?',ARRAY['4/10','10/10','3/10','4/20']::TEXT[],0,'7 − 3 = 4.',3,ARRAY[]::TEXT[],NULL,8,'c_mat-zlomky-pocitani',NULL,NOW()),
