('q_mat-zlomky-pocitani_10','Který zlomek je největší: 2/3, 3/4, 5/8?',ARRAY['5/8','Jsou stejné','2/3','3/4']::TEXT[],3,'Převedeme na 24: 16/24, 18/24, 15/24.',4,ARRAY[]::TEXT[],NULL,10,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_11','Kolik je 1 − 3/7?',ARRAY['2/7','7/3','4/7','3/7']::TEXT[],2,'1 = 7/7 a 7/7 − 3/7 = 4/7.',4,ARRAY[]::TEXT[],NULL,11,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_12','Jana snědla 1/4 pizzy a Petr 2/4. Kolik pizzy zbylo?',ARRAY['0','3/4','1/4','2/4']::TEXT[],2,'1 − 3/4 = 1/4.',5,ARRAY[]::TEXT[],NULL,12,'c_mat-zlomky-pocitani',NULL,NOW()),
